package com.codegym.product.dao;
import com.codegym.product.model.Product; import java.math.BigDecimal; import java.sql.*; import java.util.*;
public class ProductDAO { private static final String URL="jdbc:mysql://localhost:3306/product_db?useSSL=false&serverTimezone=UTC"; private static final String USER="root"; private static final String PASSWORD=""; static{try{Class.forName("com.mysql.cj.jdbc.Driver");}catch(ClassNotFoundException e){throw new ExceptionInInitializerError(e);}} private Connection connect()throws SQLException{return DriverManager.getConnection(URL,USER,PASSWORD);} private Product map(ResultSet r)throws SQLException{return new Product(r.getInt("id"),r.getString("name"),r.getBigDecimal("price"),r.getInt("quantity"));} public List<Product> findAll()throws SQLException{List<Product> out=new ArrayList<>();try(Connection c=connect();PreparedStatement p=c.prepareStatement("SELECT id,name,price,quantity FROM products ORDER BY id")){try(ResultSet r=p.executeQuery()){while(r.next())out.add(map(r));}}return out;} public Product findById(int id)throws SQLException{try(Connection c=connect();PreparedStatement p=c.prepareStatement("SELECT id,name,price,quantity FROM products WHERE id=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){return r.next()?map(r):null;}}} public void save(Product x)throws SQLException{String sql=x.getId()==0?"INSERT INTO products(name,price,quantity) VALUES(?,?,?)":"UPDATE products SET name=?,price=?,quantity=? WHERE id=?";try(Connection c=connect();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,x.getName());p.setBigDecimal(2,x.getPrice());p.setInt(3,x.getQuantity());if(x.getId()!=0)p.setInt(4,x.getId());p.executeUpdate();}} public void delete(int id)throws SQLException{try(Connection c=connect();PreparedStatement p=c.prepareStatement("DELETE FROM products WHERE id=?")){p.setInt(1,id);p.executeUpdate();}} }
